objs={'3a':[(1,2),(1,3)],'6a':[(1,7),(2,7)],'7':[(2,5),(3,5)],'8':[(3,1),(3,2)],'6b':[(4,8),(4,9)],'3b':[(5,4),(5,5)],'9':[(6,2),(7,2)],'4':[(6,8),(7,8)],'3c':[(8,0),(9,0)],'1':[(8,5),(8,6)],'5':[(9,7),(9,8)]}
# use coordinates absolute and simultaneous update top-down
occ=set((0,c) for c in range(10))
for cells in objs.values(): occ.update(cells)
# iterate objects by minimum row ascending each round; update occupancy
for iteration in range(30):
 moved=False
 for name in sorted(objs,key=lambda n:min(r for r,c in objs[n])):
  cells=objs[name]
  dest=[(r-1,c) for r,c in cells]
  if min(r for r,c in dest)<1 or any(p in occ and p not in cells for p in dest):
   continue
  for p in cells: occ.remove(p)
  for p in dest: occ.add(p)
  objs[name]=dest;moved=True
 if not moved: break
print(iteration,objs)
out=[[0]*10 for _ in range(10)]
out[0]=[2]*10
colors={'3a':3,'6a':6,'7':7,'8':8,'6b':6,'3b':3,'9':9,'4':4,'3c':3,'1':1,'5':5}
for n,cells in objs.items():
 for r,c in cells: out[r][c]=colors[n]
print('\n'.join(' '.join(map(str,row)) for row in out))
